            "--cap-drop",
            "ALL",
            "--disable-userns",
            "--proc",
            "/proc",
            "--dev",
            "/dev",
            "--ro-bind",
            "/usr",
            "/usr",
            "--ro-bind",
            "/bin",
            "/bin",
            "--ro-bind-try",
            "/lib",
            "/lib",
            "--ro-bind-try",
            "/lib64",
            "/lib64",
            "--tmpfs",
            "/run",
            "--dir",
            "/home",
            "--dir",
            "/home/martin",
            "--dir",
            "/home/martin/.local",
            "--dir",
            "/home/martin/.local/bin",
            "--ro-bind",
            "/home/martin/.local/bin/uv",
