        "    sleep 5\n"
        "    ;;\n"
        "  malformed_ack)\n"
        '    IFS= read -r -N 1 -u "$ACGS_CLEAN_SIBLING_STARTUP_BARRIER_FD" _acgs_release\n'
        '    printf ACGS_BAD_STARTUP_ACK >&"$ACGS_CLEAN_SIBLING_STATUS_FD"\n'
        "    exit 2\n"
