        "  duplicate_ack)\n"
        '    IFS= read -r -N 1 -u "$ACGS_CLEAN_SIBLING_STARTUP_BARRIER_FD" _acgs_release\n'
        '    printf ACGS_STARTUP_ACK_V1_CLOSED_UNSET >&"$ACGS_CLEAN_SIBLING_STATUS_FD"\n'
        '    printf ACGS_STARTUP_ACK_V1_CLOSED_UNSET >&"$ACGS_CLEAN_SIBLING_STATUS_FD"\n'
        "    exit 0\n"
        "    ;;\n"
        "  ack_only)\n"
        '    IFS= read -r -N 1 -u "$ACGS_CLEAN_SIBLING_STARTUP_BARRIER_FD" _acgs_release\n'
        '    printf ACGS_STARTUP_ACK_V1_CLOSED_UNSET >&"$ACGS_CLEAN_SIBLING_STATUS_FD"\n'
        "    exit 0\n"
        "    ;;\n"
