        'QUOTA_FUSE_STARTTIME="$(awk \'{print $22}\' "/proc/$QUOTA_FUSE_PID/stat")"\n'
        f"{functions}\n"
        'trap \'kill -KILL "$QUOTA_FUSE_PID" >/dev/null 2>&1 || true; '
        'wait "$QUOTA_FUSE_PID" 2>/dev/null || true\' EXIT\n'
        "quota_fuse_read_stat\n"
