    subprocess.run(
        ["git", "worktree", "add", "--detach", str(baseline_worktree), "HEAD"],
        cwd=source_repo,
        stdout=subprocess.DEVNULL,
        check=True,
    )
    parent = tmp_path / "caller"
    parent.mkdir(mode=0o700)
