    subprocess.run(["git", "add", "tracked"], cwd=source_repo, check=True)
    subprocess.run(["git", "commit", "-qm", "base"], cwd=source_repo, check=True)
    parent = tmp_path / "caller"
    parent.mkdir(mode=0o700)
