SOURCE_REPO="$3"
TMP_PARENT="$4"
TMP_ROOT="$5"
WORKTREES_BEFORE="$6"
SOURCE_STATUS_BEFORE="$7"
OWNER_MARKER="$TMP_ROOT/.acgs-clean-sibling-owned"
