    assert "if digest.hexdigest() != expected_sha256:\n    raise SystemExit(70)" in (uv_fd_verifier)
    assert "if os.lseek(fd, 0, os.SEEK_CUR) != 0:\n    raise SystemExit(70)" in (uv_fd_verifier)
